//===- matmul.cu - PolyKernel generated MatMul kernel -----------*- CUDA -*-===//
//
// AUTO-GENERATED by `polykernel-opt --lower-to-cuda` (Todo 10 / Wave 2).
// Do not edit by hand; re-run the pass to regenerate.
//
// Tiled SHARED-MEMORY GEMM (the T10 tiled SCALAR baseline; NO tensor cores /
// WMMA — those land in Wave 4): C[M,N] = A[M,K] @ B[K,N]. Batched leading dims
// are flattened into M by the caller (matching golden's np.matmul on
// [...,M,K] @ [K,N]). Each block computes one BLOCK_M x BLOCK_N output tile,
// accumulating over K in BLOCK_K-wide tiles staged through shared memory.
//
// ROUNDING CONTRACT (matches tests/golden/golden.py): bf16 inputs upcast exactly
// to fp32 for the multiply-accumulate; the fp32 accumulator is rounded back to
// bf16 (RNE) on store. Bounds checks handle M/N/K that are not tile multiples.
// Written against the portable template (kernels/template/kernel_common.h) so it
// compiles UNCHANGED under `nvcc -DPOLYKERNEL_CUDA` and `hipcc -DPOLYKERNEL_HIP`.
//
//===----------------------------------------------------------------------===//

#include "../template/kernel_common.h"

namespace {

// Output tile per block + K-tile width. One thread (tx, ty) computes one output
// element C[row, col]; blockDim == (kBlockN, kBlockM) == 16 x 16 == 256 threads.
constexpr int kBlockM = 16;
constexpr int kBlockN = 16;
constexpr int kBlockK = 16;

// One block per BLOCK_M x BLOCK_N output tile. gridDim.x tiles N (columns),
// gridDim.y tiles M (rows). Shared memory stages one BLOCK_K-wide slice of A
// (BLOCK_M x BLOCK_K) and B (BLOCK_K x BLOCK_N) per K-tile iteration.
PK_GLOBAL void matmul_kernel(const pk_bf16 *__restrict__ A,
                             const pk_bf16 *__restrict__ B,
                             pk_bf16 *__restrict__ C, int M, int N, int K) {
  PK_SHARED pk_bf16 As[kBlockM][kBlockK];
  PK_SHARED pk_bf16 Bs[kBlockK][kBlockN];

  const int tx = threadIdx.x; // column within the output tile [0, kBlockN)
  const int ty = threadIdx.y; // row within the output tile    [0, kBlockM)
  const int row = blockIdx.y * kBlockM + ty;
  const int col = blockIdx.x * kBlockN + tx;

  // fp32 accumulator (matches golden: np.matmul on fp32(bf16(a)), fp32(bf16(b))).
  float acc = 0.0f;

  const int numKTiles = (K + kBlockK - 1) / kBlockK;
  for (int t = 0; t < numKTiles; ++t) {
    // Stage A[row, t*kBlockK + tx] and B[t*kBlockK + ty, col] into shared mem.
    // Out-of-bounds loads (non-tile-multiple M/N/K) read as 0 so they never
    // contribute to the accumulator.
    int aCol = t * kBlockK + tx;
    As[ty][tx] = (row < M && aCol < K) ? A[static_cast<size_t>(row) * K + aCol]
                                       : pk_float2bf16(0.0f);
    int bRow = t * kBlockK + ty;
    Bs[ty][tx] = (bRow < K && col < N) ? B[static_cast<size_t>(bRow) * N + col]
                                       : pk_float2bf16(0.0f);
    pk_syncthreads();

    // Accumulate this K-tile in fp32 (bf16 upcast exactly on each read).
#pragma unroll
    for (int kk = 0; kk < kBlockK; ++kk)
      acc += pk_bf162float(As[ty][kk]) * pk_bf162float(Bs[kk][tx]);
    pk_syncthreads();
  }

  // Round the fp32 accumulator back to bf16 (RNE) and store, within bounds.
  if (row < M && col < N)
    C[static_cast<size_t>(row) * N + col] = pk_float2bf16(acc);
}

} // namespace

// Host-callable launch entry (the launch_*-style ABI). C[M,N] = A[M,K] @ B[K,N];
// batched leading dims are flattened into M by the caller. The stream is passed
// as void* to keep the signature backend-agnostic and cast to the backend stream
// type (pk_stream_t) inside.
void launch_matmul(const pk_bf16 *A, const pk_bf16 *B, pk_bf16 *C, int M, int N,
                   int K, void *stream) {
  dim3 block(kBlockN, kBlockM);
  dim3 grid((N + kBlockN - 1) / kBlockN, (M + kBlockM - 1) / kBlockM);
  pk_stream_t s = static_cast<pk_stream_t>(stream);
  PK_LAUNCH(matmul_kernel, grid, block, 0, s, A, B, C, M, N, K);
  PK_CHECK(pk_get_last_error());
}
